<?php declare(strict_types=1); ?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rezervasyon yönetimi</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1150px;margin:35px auto;padding:0 18px}.item{background:white;border:1px solid #e7ece8;border-radius:13px;padding:17px;margin:12px 0;display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:14px;align-items:center}.muted{color:#6d796f;font-size:13px}.tag{background:#eef4ef;padding:5px 8px;border-radius:15px;font-size:12px}select,button{padding:9px;border:1px solid #dfe6e0;border-radius:8px}button{background:#176b50;color:white;font-weight:700;border:0}@media(max-width:700px){.item{grid-template-columns:1fr 1fr}}
/* Consistent admin links and actions */
a{color:#176b50;text-decoration:none;transition:color .18s ease,background-color .18s ease,border-color .18s ease}a:hover{color:#104c39;text-decoration:none}td a:not([class]),.table-wrap a:not([class]){display:inline-flex;align-items:center;justify-content:center;padding:7px 11px;border:1px solid #dce9e0;border-radius:8px;background:#f5faf6;color:#176b50;font-size:12px;font-weight:750;white-space:nowrap}td a:not([class]):hover,.table-wrap a:not([class]):hover{background:#eaf4ee;border-color:#b9d8c4}button,input[type=submit]{cursor:pointer;font:inherit}button{transition:filter .18s ease,transform .18s ease}button:hover,input[type=submit]:hover{filter:brightness(.96)}
</style></head><body><main class="wrap"><h1>Rezervasyonlar</h1><p class="muted">Misafir taleplerini inceleyin ve rezervasyon durumlarını yönetin.</p><?php foreach($bookings as $b): ?><article class="item"><div><strong><?= e($b['title']) ?></strong><div class="muted"><?= e($b['guest_name']) ?> · <?= e($b['guest_email']) ?></div><div class="muted"><?= e($b['booking_code']) ?></div> </div><div><?= e(date('d.m.Y',strtotime($b['check_in']))) ?> – <?= e(date('d.m.Y',strtotime($b['check_out']))) ?><div class="muted"><?= (int)$b['guests'] ?> misafir</div></div><div><strong><?= e(number_format((float)$b['total'],0,',','.')) ?> <?= e($b['currency']) ?></strong><div class="muted"><span class="tag"><?= e($b['status']) ?></span></div></div><form method="post" action="/admin/bookings/status"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><select name="status"><option value="pending" <?= $b['status']==='pending'?'selected':'' ?>>Bekliyor</option><option value="confirmed" <?= $b['status']==='confirmed'?'selected':'' ?>>Onayla</option><option value="cancelled" <?= $b['status']==='cancelled'?'selected':'' ?>>İptal</option><option value="completed" <?= $b['status']==='completed'?'selected':'' ?>>Tamamlandı</option></select> <button type="submit">Kaydet</button></form></article><?php endforeach; ?><?php if(!$bookings): ?><p>Henüz rezervasyon bulunmuyor.</p><?php endif; ?></main></body></html>